import { FastRateLimit } from 'fast-ratelimit';
import { nanoid } from 'nanoid';
import { Window } from './window.js';
import { CrawlerRenderer } from './crawler/index.js';

// _htmlBuffers.js is generated by scripts/build.js
import htmlBuffers from "./_htmlBuffers.js";

import { createConfig } from './config.js';
import { enqueueWindowInput, getWindow, registerWindow, deregisterWindow, setWindowSchedulerPaused } from './state.js';

export const WINDOW_MAINTENANCE_IDLE = 0;
export const WINDOW_MAINTENANCE_WAITING_FOR_ACK = 1;
export const WINDOW_MAINTENANCE_DISCONNECTED = 2;

export function createRoot(rootFn) {
  let root = new Root(rootFn);
  let processEnv = globalThis.process && globalThis.process.env;

  root.configure(processEnv);

  return root;
}

class Root {

  constructor(rootFn) {
    this.rootFn = rootFn;

    this.externalWindowIdMapping = new Map();
    this.windowConnectionMap = new Map();
    this.windows = new Set();
    this.retainedOutputBytes = 0;
    this.outputProgressHead = null;
    this.outputProgressTail = null;
    this.globalOutputBackpressurePaused = false;
    this.outputPressureTimer = null;
    this.outputPressureChecking = false;
    this.windowMaintenanceTimer = null;
    this.windowMaintenanceLastTick = 0;
    this.windowMaintenanceBuckets = new Array(256).fill(null);
    this.config = null;
    this.rateLimitDisabled = false;
    this.messageLimiter = null;
    this.windowCreationLimiter = null;

    this.droppedMessagesCount = 0;

    /*
    setInterval(() => {
      if (this.droppedMessagesCount > 0) {
        console.log('Dropped messages: ' + this.droppedMessagesCount);
        this.droppedMessagesCount = 0;
      }
    }, 2000);
    */

    this.disableHtmlCompression = false;
  }

  hasWindow(windowId) {
    let window = getWindow(windowId);
    return window != null && !window.destroyed;
  }

  setRateLimit({ disabled }) {
    this.rateLimitDisabled = disabled;

    if (disabled) {
      // assign no-op rate limiters 
      this.messageLimiter = {
        consumeSync: () => true
      };

      this.windowCreationLimiter = {
        consumeSync: () => true
      };
    } else {
      this._configureRateLimiters();
    }
  }

  setDisableHtmlCompression() {
    this.disableHtmlCompression = true;
  }

  configure(env) {
    let previousConfig = this.config;
    let config = createConfig(env);
    let rateLimitConfigChanged = !previousConfig ||
      previousConfig.rateLimitWindowInputThreshold !== config.rateLimitWindowInputThreshold ||
      previousConfig.rateLimitWindowInputTtlSeconds !== config.rateLimitWindowInputTtlSeconds ||
      previousConfig.rateLimitWindowCreationThreshold !== config.rateLimitWindowCreationThreshold ||
      previousConfig.rateLimitWindowCreationTtlSeconds !== config.rateLimitWindowCreationTtlSeconds;

    this.config = config;
    this.crawlerRenderingEnabled = config.enableCrawlerRenderer;
    this.crawlerRenderer = this.crawlerRenderingEnabled ? (this.crawlerRenderer || new CrawlerRenderer()) : null;

    for (let window of this.windows) {
      if (window.outputRetentionTracking) {
        this._evaluateWindowOutputFlowControl(window);
      }
    }
    this._evaluateGlobalOutputFlowControl();

    if (rateLimitConfigChanged && !this.rateLimitDisabled) {
      this._configureRateLimiters();
    }
  }

  _configureRateLimiters() {
    // TODO: we'll want to broadcast these limits to the client so it can
    // adjust its message sending rate.
    this.messageLimiter = new FastRateLimit({
      threshold: this.config.rateLimitWindowInputThreshold,
      ttl: this.config.rateLimitWindowInputTtlSeconds
    });

    this.windowCreationLimiter = new FastRateLimit({
      threshold: this.config.rateLimitWindowCreationThreshold,
      ttl: this.config.rateLimitWindowCreationTtlSeconds
    });
  }

  _enqueueMessage(windowId, message) {
    // TODO: move the length check to the websocket server's max message size
    // do this once we set up client-side rate limiting
    if (
      message.byteLength < 2 ||
      message.byteLength >= this.config.maxInputEventBufferSize
    ) {
      this.droppedMessagesCount++;
      return;
    }

    // `ws` already delivers binary frames as Buffers. Re-wrapping every input
    // creates another Buffer view object on both the click and pong paths.
    let inputBuffer = Buffer.isBuffer(message) ? message : Buffer.from(message);
    let txPortId = inputBuffer.readUInt16LE(0);
    let window = getWindow(windowId);

    if (!window || window.destroyed) {
      return;
    }

    // Port zero is reserved for acknowledgement and connection control.
    if (txPortId == 0) {
      if (inputBuffer.length === 2) {
        window.requestDestroy();
        return;
      }

      if (inputBuffer.length !== 6) {
        this.droppedMessagesCount++;
        return;
      }

      let readOffset = inputBuffer.readUInt32LE(2);
      if (!this._registerWindowInput(window, readOffset)) {
        this.droppedMessagesCount++;
      }
      return;
    }

    // A normal event needs the acknowledgement header plus at least the
    // empty encoded argument list. Register progress before rate limiting so
    // a dropped application event can still release retained output.
    if (inputBuffer.length < 10) {
      this.droppedMessagesCount++;
      return;
    }

    if (!this._registerWindowInput(window, inputBuffer.readUInt32LE(2))) {
      this.droppedMessagesCount++;
      return;
    }

    // TODO: print on a regular interval the amount of messages that are being dropped
    if (!this.messageLimiter.consumeSync(windowId)) {
      this.droppedMessagesCount++;
      return;
    }

    // TODO: apply window & handler specific limits

    enqueueWindowInput(windowId, inputBuffer);
  }

  applyNewConnection(ws, { url, headers, ipAddress }, auxContext) {

    let params = new URLSearchParams(url.split('?')[1]);

    // then, get the values from the params object
    let externalWindowId = params.get('wi') || '';
    let readOffset = parseInt(params.get('ro'));
    let viewportSize = params.get('vs').split('x').map((num) => parseInt(num));
    let locationString = params.get('lo');

    let isUnderRateLimit = this.windowCreationLimiter.consumeSync(ipAddress);

    if (!isUnderRateLimit) {
      // 3010 is code for "excessive window creation" -- the client will close and not reconnect.
      ws.close(3010);
      return;
    }

    let cookieString = headers.get('cookie') || '';

    // href is the combination of:
    // - the protocol+hostname+port (take it from the Origin header for security)
    // - pathname
    // - searchParams
    let origin = headers.get('origin') || '';
    let href = origin + locationString;

    let pageParams = {
      windowId: null,
      href,
      viewportSize,
      readOffset,
      cookieString,
    };

    if (externalWindowId) {
      pageParams.windowId = externalWindowId;

      let windowId = this._convertExternalWindowIdToInternal(externalWindowId);

      if (this.hasWindow(windowId)) {
        this.reconnectWindow(ws, pageParams);
      } else {
        // 3001 is the code for "no such window" -- the client will reload and re-initialize for a new window
        ws.close(3001);
        return;
      }
    } else {
      let externalWindowId = nanoid();
      pageParams.windowId = externalWindowId;
      this.initWindow(ws, pageParams, auxContext);
    }
  }

  initWindow(ws, pageParams, auxContext) {

    // TODO: pass request's ip address here, and rate limit window creation based on ip address
    let window = new Window(this, pageParams, auxContext, this.rootFn, () => {});

    this.externalWindowIdMapping.set(pageParams.windowId, window.id);

    registerWindow(window);
    this._trackWindow(window);
    window.onBuffer(this._setupWsListeners(ws, window.id));
    window.enableOutputRetentionTracking();

    window.start();

    window.onDestroy(() => {
      this.externalWindowIdMapping.delete(pageParams.windowId);
      this._untrackWindow(window);
      deregisterWindow(window);
      this._closeWindowConnection(window.id);
    });

  }

  async getHtmlResponse({ url, headers, ipAddress, isSecure, auxContext = null }) {
    let isUnderRateLimit = this.windowCreationLimiter.consumeSync(ipAddress);

    if (!isUnderRateLimit) {
      return {
        statusCode: 429,
        headers: {
          'Content-Type': 'text/plain',
          'Cache-Control': 'no-store',
        },
        body: 'Too many requests'
      }
    }

    let responseHeaders = {
      'Content-Type': 'text/html; charset=utf-8',
      'Vary': 'Accept',
      'Cache-Control': 'no-store',
    };

    if (this.crawlerRenderingEnabled && this.crawlerRenderer.shouldUseRenderer(headers)) {

      // href is combination of:
      // - the protocol+hostname+port 
      // - pathname
      // - searchParams

      // in cloudflare workers Service Worker mode, the url might contain the host
      // let's pick it out for now
      // TODO: clean up the flow
      if (!(url.startsWith('https://') || url.startsWith('http://'))) {
        url = (isSecure ? 'https://' : 'http://') + headers.get('host') + url;
      }

      let href = url;

      // TODO: check if we have a cached response for this request
      let html = await this.renderHtml({ headers, href, auxContext });
      responseHeaders['Content-Length'] = Buffer.byteLength(html);

      return {
        statusCode: 200,
        headers: responseHeaders,
        body: html
      };
    }

    let acceptEncoding = headers.get('accept-encoding') || '';
    let algo;
    let html;

    // in cloudflare workers, we need to be sending uncompressed HTML
    // seemingly CF doesn't support pre-compressed HTML
    if (this.disableHtmlCompression) {
      html = htmlBuffers.uncompressed;
    } else {
      if (acceptEncoding.indexOf('br') > -1) {
        algo = 'br';
        html = htmlBuffers.br;
      } else if (acceptEncoding.indexOf('gzip') > -1) {
        algo = 'gzip';
        html = htmlBuffers.gzip;
      } else {
        html = htmlBuffers.uncompressed;
      }
    }

    responseHeaders['Content-Length'] = html.byteLength;

    if (algo) {
      responseHeaders['Content-Encoding'] = algo;
    }

    return {
      statusCode: 200,
      headers: responseHeaders,
      body: html
    };
  }

  async renderHtml({ headers, href, auxContext = null }) {
    let cookieString = headers.get('cookie') || '';

    let pageParams = {
      windowId: nanoid(),
      href,

      // TODO: get viewport size from request
      viewportSize: [1920, 1080],

      readOffset: 0,
      cookieString
    };

    let htmlRenderContext = this.crawlerRenderer.createHtmlRenderingContext();

    let window = new Window(this, pageParams, auxContext, this.rootFn, buf => {
      htmlRenderContext.feedBuffer(buf);
    });

    registerWindow(window);
    this._trackWindow(window);

    window.start();

    window.onDestroy(() => {
      this._untrackWindow(window);
      deregisterWindow(window);
    });

    return new Promise((resolve, reject) => {
      htmlRenderContext.onRenderComplete((html) => {
        window.destroy();
        resolve(html);
      });

      htmlRenderContext.onRenderError((err) => {
        window.destroy();
        reject(err);
      });
    });
  }

  _convertExternalWindowIdToInternal(externalWindowId) {
    return this.externalWindowIdMapping.get(externalWindowId);
  }

  reconnectWindow(ws, pageParams) {
    let windowId = this._convertExternalWindowIdToInternal(pageParams.windowId);

    let window = getWindow(windowId);

    if (!window || window.destroyed) {
      ws.close(3001);
      return;
    }

    // Only the newest websocket may publish to or disconnect this window.
    window.onBuffer(this._setupWsListeners(ws, windowId));

    window.reconnect(pageParams);
    // Reconnection may have no unread application output. Send one ephemeral
    // probe so the browser can confirm the replacement socket immediately.
    this._sendWindowProbe(window);
  }

  _setupWsListeners(ws, windowId) {
    let previousConnection = this.windowConnectionMap.get(windowId);
    let connection = { ws };
    this.windowConnectionMap.set(windowId, connection);

    if (previousConnection && previousConnection.ws !== ws) {
      previousConnection.ws.close();
    }

    ws.on('message', (message) => {
      if (this.windowConnectionMap.get(windowId) !== connection) {
        return;
      }

      this._enqueueMessage(windowId, message);
    });

    ws.on('close', () => {
      if (this.windowConnectionMap.get(windowId) !== connection) {
        return;
      }
      this.windowConnectionMap.delete(windowId);
      this.disconnectWindow(windowId);
    });

    return buf => {
      if (this.windowConnectionMap.get(windowId) === connection) {
        ws.send(buf);
      }
    };
  }

  _closeWindowConnection(windowId, code) {
    let connection = this.windowConnectionMap.get(windowId);

    if (connection) {
      this.windowConnectionMap.delete(windowId);
      connection.ws.close(code);
    }
  }

  _trackWindow(window) {
    this.windows.add(window);
    let now = Date.now();
    window.maintenanceState = WINDOW_MAINTENANCE_IDLE;
    this._scheduleWindowMaintenance(
      window,
      now + this._getWindowIdleProbeDelay(window)
    );
    this._startWindowMaintenance();
  }

  _untrackWindow(window) {
    this._prepareWindowForDestroy(window);
    this.windows.delete(window);
    if (this.windows.size === 0) {
      clearInterval(this.windowMaintenanceTimer);
      this.windowMaintenanceTimer = null;
    }
  }

  _prepareWindowForDestroy(window) {
    this._unlinkWindowMaintenance(window);
    clearTimeout(window.outputStallTimer);
    window.outputStallTimer = null;
    window.outputBackpressurePaused = false;
    window.globalOutputBackpressurePaused = false;
    window.maintenanceState = WINDOW_MAINTENANCE_DISCONNECTED;
    this._syncWindowSchedulerPause(window);
  }

  _startWindowMaintenance() {
    if (this.windowMaintenanceTimer) {
      return;
    }

    let tickMs = Math.max(1, this.config.windowMaintenanceTickMs);
    this.windowMaintenanceLastTick = Math.floor(Date.now() / tickMs);
    this.windowMaintenanceTimer = setInterval(() => {
      this._runWindowMaintenance();
    }, tickMs);
    this.windowMaintenanceTimer.unref?.();
  }

  _unlinkWindowMaintenance(window) {
    let bucketIndex = window.maintenanceBucketIndex;
    if (bucketIndex < 0) {
      return;
    }

    let previous = window.maintenancePrev;
    let next = window.maintenanceNext;
    if (previous) {
      previous.maintenanceNext = next;
    } else {
      this.windowMaintenanceBuckets[bucketIndex] = next;
    }
    if (next) {
      next.maintenancePrev = previous;
    }

    window.maintenancePrev = null;
    window.maintenanceNext = null;
    window.maintenanceBucketIndex = -1;
  }

  _scheduleWindowMaintenance(window, deadline) {
    if (window.destroyed || !this.windows.has(window)) {
      return;
    }

    this._unlinkWindowMaintenance(window);
    let tickMs = Math.max(1, this.config.windowMaintenanceTickMs);
    // Keep the exact fractional tick so other maintenance users can recover
    // the deadline without adding a second per-window timestamp.
    let dueTick = deadline / tickMs;
    let bucketIndex = Math.ceil(dueTick) % this.windowMaintenanceBuckets.length;
    let head = this.windowMaintenanceBuckets[bucketIndex];

    window.maintenanceDueTick = dueTick;
    window.maintenanceBucketIndex = bucketIndex;
    window.maintenancePrev = null;
    window.maintenanceNext = head;
    if (head) {
      head.maintenancePrev = window;
    }
    this.windowMaintenanceBuckets[bucketIndex] = window;
  }

  _runWindowMaintenance(now = Date.now()) {
    let tickMs = Math.max(1, this.config.windowMaintenanceTickMs);
    let currentTick = Math.floor(now / tickMs);
    let elapsedTicks = currentTick - this.windowMaintenanceLastTick;
    if (elapsedTicks <= 0) {
      return;
    }

    let bucketCount = this.windowMaintenanceBuckets.length;
    let firstTick = elapsedTicks > bucketCount
      ? currentTick - bucketCount + 1
      : this.windowMaintenanceLastTick + 1;

    for (let tick = firstTick; tick <= currentTick; tick++) {
      let bucketIndex = tick % bucketCount;
      let window = this.windowMaintenanceBuckets[bucketIndex];

      while (window) {
        let next = window.maintenanceNext;
        if (window.maintenanceDueTick <= currentTick) {
          this._unlinkWindowMaintenance(window);
          this._maintainWindow(window, now);
        }
        window = next;
      }
    }

    this.windowMaintenanceLastTick = currentTick;
  }

  _maintainWindow(window, now) {
    if (window.destroyed) {
      return;
    }

    if (window.maintenanceState === WINDOW_MAINTENANCE_DISCONNECTED) {
      window.destroy();
      return;
    }

    if (window.maintenanceState === WINDOW_MAINTENANCE_WAITING_FOR_ACK) {
      window.connected = false;
      window.maintenanceState = WINDOW_MAINTENANCE_DISCONNECTED;
      this._closeWindowConnection(window.id);
      if (this.lowMemoryMode) {
        window.destroy();
        return;
      }
      this._scheduleWindowMaintenance(
        window,
        now + this.config.disconnectedWindowDestroyMs
      );
      return;
    }

    if (window.deleteBlockCount > 300) {
      window.flushBlockDeleteQueue();
    }

    this._sendWindowProbe(window, now);
  }

  _sendWindowProbe(window, now = Date.now()) {
    if (
      window.destroyed ||
      !window.connected ||
      !window.bufferFn ||
      window.maintenanceState !== WINDOW_MAINTENANCE_IDLE
    ) {
      return;
    }

    window.maintenanceState = WINDOW_MAINTENANCE_WAITING_FOR_ACK;
    window.probeReadOffset = window.global_readOffset;
    window.sendPing();
    this._scheduleWindowMaintenance(
      window,
      now + this.config.idleProbeTimeoutMs
    );
  }

  _expandWindowReadOffset(window, wireOffset) {
    let range = 0x100000000;
    let base = Math.floor(window.global_readOffset / range) * range;
    let readOffset = base + wireOffset;

    if (readOffset < window.global_readOffset) {
      readOffset += range;
    }
    return readOffset;
  }

  _registerWindowInput(window, wireOffset) {
    let readOffset = this._expandWindowReadOffset(window, wireOffset);
    try {
      window.registerClientAcknowledgement(readOffset);
    } catch {
      return false;
    }

    let now = Date.now();
    window.connected = true;
    window.maintenanceState = WINDOW_MAINTENANCE_IDLE;
    window.outputUnacknowledgedAt = window.retainedOutputBytes > 0 ? now : 0;
    this._scheduleWindowMaintenance(
      window,
      this._getWindowNextProbeDeadline(window, now)
    );
    return true;
  }

  _markWindowReconnected(window) {
    let now = Date.now();
    window.connected = true;
    window.maintenanceState = WINDOW_MAINTENANCE_IDLE;
    window.outputUnacknowledgedAt = window.retainedOutputBytes > 0 ? now : 0;
    this._scheduleWindowMaintenance(
      window,
      this._getWindowNextProbeDeadline(window, now)
    );
  }

  _getWindowIdleProbeDelay(window) {
    let jitter = this.config.idleProbeJitterMs > 0
      ? ((window.id * 2654435761) >>> 0) % this.config.idleProbeJitterMs
      : 0;
    return this.config.idleProbeIntervalMs + jitter;
  }

  _getWindowNextProbeDeadline(window, now) {
    return window.outputUnacknowledgedAt > 0
      ? window.outputUnacknowledgedAt +
        this.config.staleOutputAcknowledgementMs
      : now + this._getWindowIdleProbeDelay(window);
  }

  _syncWindowSchedulerPause(window) {
    let paused = !window.destroyed && (
      window.outputBackpressurePaused ||
      window.globalOutputBackpressurePaused
    );

    if (window.schedulerOutputPaused === paused) {
      return;
    }

    window.schedulerOutputPaused = paused;
    setWindowSchedulerPaused(window, paused);
  }

  _getWindowPublicationCount(window) {
    return window.publicationEndOffset === 0
      ? 0
      : 1 + (window.publications
        ? window.publications.length - window.publicationHead
        : 0);
  }

  _enableWindowOutputRetention(window) {
    window.globalOutputBackpressurePaused =
      this.globalOutputBackpressurePaused;
    this._syncWindowSchedulerPause(window);
    this._updateWindowRetainedOutput(window);
    this._evaluateWindowOutputFlowControl(window);
    this._evaluateGlobalOutputFlowControl();
  }

  _getHalfOutputLimit(limit) {
    return limit > 0 ? Math.max(1, Math.floor(limit / 2)) : 0;
  }

  _isWindowAtRecyclingAcknowledgementThreshold(window) {
    let threshold = this.config.recyclingAcknowledgementBytes;
    return threshold > 0 && window.retainedOutputBytes >= threshold;
  }

  _isWindowAtHardOutputLimit(window) {
    let config = this.config;
    let maxBytes = config.maxUnacknowledgedOutputBytes;
    let maxPublications = config.maxUnacknowledgedPublications;

    return (
      maxBytes > 0 && window.retainedOutputBytes >= maxBytes
    ) || (
      maxPublications > 0 &&
      this._getWindowPublicationCount(window) >= maxPublications
    );
  }

  _isWindowBelowResumeLimit(window) {
    let config = this.config;
    let resumeBytes = this._getHalfOutputLimit(
      config.maxUnacknowledgedOutputBytes
    );
    let resumePublications = this._getHalfOutputLimit(
      config.maxUnacknowledgedPublications
    );
    let belowBytes = resumeBytes === 0 ||
      window.retainedOutputBytes < resumeBytes;
    let belowPublications = resumePublications === 0 ||
      this._getWindowPublicationCount(window) < resumePublications;

    return belowBytes && belowPublications;
  }

  _requestWindowAcknowledgement(window) {
    if (
      window.destroyed ||
      !window.connected ||
      !window.bufferFn ||
      window.maintenanceState !== WINDOW_MAINTENANCE_IDLE
    ) {
      return;
    }

    this._sendWindowProbe(window);
  }

  _scheduleWindowStallCheck(window) {
    clearTimeout(window.outputStallTimer);
    window.outputStallTimer = null;

    let timeout = this.config.outputStallTimeoutMs;
    if (!window.outputBackpressurePaused || timeout <= 0) {
      return;
    }

    let elapsed = Date.now() - window.outputLastProgressAt;
    window.outputStallTimer = setTimeout(() => {
      window.outputStallTimer = null;
      this._checkWindowOutputStall(window);
    }, Math.max(1, timeout - elapsed));
    window.outputStallTimer.unref?.();
  }

  _checkWindowOutputStall(window) {
    if (window.destroyed || !window.outputBackpressurePaused) {
      return;
    }

    let timeout = this.config.outputStallTimeoutMs;
    if (timeout <= 0) {
      return;
    }

    if (Date.now() - window.outputLastProgressAt < timeout) {
      this._scheduleWindowStallCheck(window);
      return;
    }

    this._expireWindowForOutputBacklog(window, 'window-stalled');
  }

  _setWindowOutputPaused(window, paused) {
    if (window.outputBackpressurePaused === paused) {
      return;
    }

    window.outputBackpressurePaused = paused;

    if (paused) {
      window.outputLastProgressAt = Date.now();
      this._scheduleWindowStallCheck(window);
    } else {
      clearTimeout(window.outputStallTimer);
      window.outputStallTimer = null;
    }

    this._syncWindowSchedulerPause(window);
  }

  _evaluateWindowOutputFlowControl(window) {
    if (!window.outputRetentionTracking || window.destroyed) {
      return;
    }

    let atHardLimit = this._isWindowAtHardOutputLimit(window);

    if (atHardLimit) {
      this._setWindowOutputPaused(window, true);
    } else if (
      window.outputBackpressurePaused &&
      this._isWindowBelowResumeLimit(window)
    ) {
      this._setWindowOutputPaused(window, false);
    }

    if (
      atHardLimit ||
      this._isWindowAtRecyclingAcknowledgementThreshold(window)
    ) {
      this._requestWindowAcknowledgement(window);
    }
  }

  _afterWindowOutputPublished(window) {
    this._evaluateWindowOutputFlowControl(window);
    this._evaluateGlobalOutputFlowControl();
  }

  _afterWindowOutputProgress(window, madeProgress) {
    if (madeProgress) {
      window.outputLastProgressAt = Date.now();

      if (
        window.outputBackpressurePaused &&
        this._isWindowBelowResumeLimit(window)
      ) {
        this._setWindowOutputPaused(window, false);
      } else if (window.outputBackpressurePaused) {
        this._scheduleWindowStallCheck(window);
      }
    }

    this._evaluateWindowOutputFlowControl(window);
    this._evaluateGlobalOutputFlowControl();
  }

  _unlinkOutputProgressWindow(window) {
    if (!window.outputProgressListed) {
      return;
    }

    let previous = window.outputProgressPrev;
    let next = window.outputProgressNext;

    if (previous) {
      previous.outputProgressNext = next;
    } else {
      this.outputProgressHead = next;
    }

    if (next) {
      next.outputProgressPrev = previous;
    } else {
      this.outputProgressTail = previous;
    }

    window.outputProgressPrev = null;
    window.outputProgressNext = null;
    window.outputProgressListed = false;
  }

  _appendOutputProgressWindow(window) {
    window.outputProgressPrev = this.outputProgressTail;
    window.outputProgressNext = null;
    window.outputProgressListed = true;

    if (this.outputProgressTail) {
      this.outputProgressTail.outputProgressNext = window;
    } else {
      this.outputProgressHead = window;
    }

    this.outputProgressTail = window;
  }

  _updateWindowRetainedOutput(window, madeProgress = false) {
    if (!window.outputRetentionTracking || window.destroyed) {
      return;
    }

    let retainedBytes = window.global_publishOffset - window.global_readOffset;
    let previousRetainedBytes = window.retainedOutputBytes;
    this.retainedOutputBytes += retainedBytes - previousRetainedBytes;
    window.retainedOutputBytes = retainedBytes;

    if (retainedBytes === 0) {
      window.outputUnacknowledgedAt = 0;
      this._unlinkOutputProgressWindow(window);
    } else if (!window.outputProgressListed) {
      this._appendOutputProgressWindow(window);
    } else if (madeProgress && this.outputProgressTail !== window) {
      this._unlinkOutputProgressWindow(window);
      this._appendOutputProgressWindow(window);
    }

    if (previousRetainedBytes === 0 && retainedBytes > 0) {
      let now = Date.now();
      window.outputUnacknowledgedAt = now;
      if (window.maintenanceState === WINDOW_MAINTENANCE_IDLE) {
        this._scheduleWindowMaintenance(
          window,
          now + this.config.staleOutputAcknowledgementMs
        );
      }
    }

  }

  _releaseWindowRetainedOutput(window) {
    this.retainedOutputBytes -= window.retainedOutputBytes;
    window.retainedOutputBytes = 0;
    window.outputUnacknowledgedAt = 0;
    this._unlinkOutputProgressWindow(window);
    this._evaluateGlobalOutputFlowControl();
  }

  _expireWindowForOutputBacklog(window, reason = 'unknown') {
    if (window.destroyed) {
      this._releaseWindowRetainedOutput(window);
      return;
    }

    window.outputBacklogCloseReason = reason;
    this._closeWindowConnection(window.id, 3002);
    window.destroy();
  }

  _setGlobalOutputPaused(paused) {
    if (this.globalOutputBackpressurePaused === paused) {
      return;
    }

    this.globalOutputBackpressurePaused = paused;

    for (let window of this.windows) {
      if (!window.outputRetentionTracking) {
        continue;
      }

      window.globalOutputBackpressurePaused = paused;
      this._syncWindowSchedulerPause(window);
    }
  }

  _probeRetainedOutputWindows() {
    let window = this.outputProgressHead;

    while (window) {
      let next = window.outputProgressNext;
      this._requestWindowAcknowledgement(window);
      window = next;
    }
  }

  _scheduleGlobalPressureCheck() {
    if (this.outputPressureTimer) {
      return;
    }

    let grace = this.config.outputPressureGraceMs;
    if (grace <= 0) {
      grace = 1;
    }

    this.outputPressureTimer = setTimeout(() => {
      this.outputPressureTimer = null;
      this._checkGlobalOutputPressure();
    }, grace);
    this.outputPressureTimer.unref?.();
  }

  _isWindowEligibleForPressureCull(window, now) {
    let grace = Math.max(1, this.config.outputPressureGraceMs);
    let tickMs = Math.max(1, this.config.windowMaintenanceTickMs);
    let dueAt = window.maintenanceDueTick * tickMs;

    if (window.maintenanceState === WINDOW_MAINTENANCE_DISCONNECTED) {
      let disconnectedAt = dueAt - this.config.disconnectedWindowDestroyMs;
      return now - disconnectedAt >= grace;
    }

    if (window.maintenanceState !== WINDOW_MAINTENANCE_WAITING_FOR_ACK) {
      return false;
    }

    let probeSentAt = dueAt - this.config.idleProbeTimeoutMs;
    return window.global_readOffset <= window.probeReadOffset &&
      now - probeSentAt >= grace;
  }

  _checkGlobalOutputPressure() {
    let maxRetainedBytes = this.config?.maxRetainedOutputBytes || 0;

    if (maxRetainedBytes === 0 || !this.globalOutputBackpressurePaused) {
      return;
    }

    let recoveryTarget = Math.floor(maxRetainedBytes * 0.75);
    let now = Date.now();
    let window = this.outputProgressHead;

    this.outputPressureChecking = true;

    try {
      while (window && this.retainedOutputBytes > recoveryTarget) {
        let next = window.outputProgressNext;

        if (this._isWindowEligibleForPressureCull(window, now)) {
          this._expireWindowForOutputBacklog(window, 'global-output-pressure');
        }

        window = next;
      }

      if (this.retainedOutputBytes > recoveryTarget) {
        this._probeRetainedOutputWindows();
      }
    } finally {
      this.outputPressureChecking = false;
    }

    this._evaluateGlobalOutputFlowControl();
  }

  _evaluateGlobalOutputFlowControl() {
    if (this.outputPressureChecking || !this.config) {
      return;
    }

    let maxRetainedBytes = this.config.maxRetainedOutputBytes;

    if (maxRetainedBytes <= 0) {
      clearTimeout(this.outputPressureTimer);
      this.outputPressureTimer = null;
      this._setGlobalOutputPaused(false);
      return;
    }

    this.outputPressureChecking = true;

    try {
      let softLimit = this._getHalfOutputLimit(maxRetainedBytes);

      if (this.retainedOutputBytes >= softLimit) {
        this._probeRetainedOutputWindows();
      }

      let emergencyLimit = maxRetainedBytes * 2;

      while (
        this.retainedOutputBytes > emergencyLimit &&
        this.outputProgressHead
      ) {
        this._expireWindowForOutputBacklog(
          this.outputProgressHead,
          'global-output-emergency'
        );
      }

      if (this.retainedOutputBytes >= maxRetainedBytes) {
        this._setGlobalOutputPaused(true);
        this._scheduleGlobalPressureCheck();
      } else if (
        this.globalOutputBackpressurePaused &&
        this.retainedOutputBytes <= Math.floor(maxRetainedBytes * 0.75)
      ) {
        clearTimeout(this.outputPressureTimer);
        this.outputPressureTimer = null;
        this._setGlobalOutputPaused(false);
      }
    } finally {
      this.outputPressureChecking = false;
    }

    if (this.globalOutputBackpressurePaused) {
      this._scheduleGlobalPressureCheck();
    }
  }

  _cullRetainedOutputIfNeeded() {
    this._evaluateGlobalOutputFlowControl();
  }

  disconnectWindow(windowId) {

    let window = getWindow(windowId);

    if (window) {
      window.disconnect();
      window.maintenanceState = WINDOW_MAINTENANCE_DISCONNECTED;
      let now = Date.now();
      if (this.lowMemoryMode) {
        window.destroy();
        return;
      }
      this._scheduleWindowMaintenance(
        window,
        now + this.config.disconnectedWindowDestroyMs
      );
    }
  }
}
